{
  "contract": "Yeeter",
  "closure": {
    "site_function": "yeetyeet",
    "site_call": ".call",
    "functions": ["<fallback>", "yeetyeet"],
    "justification": "The risky site in function `yeetyeet` uses a low-level value transfer which can trigger reentrance. Therefore, any function that could be called externally during this transfer, which includes `yeetyeet` itself as well as `<fallback>`, must be included in the closure."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": ["<fallback>"],
    "nesting_bound": {
      "yeetyeet": 1,
      "<fallback>": 1
    }
  },
  "phases": {
    "function": "yeetyeet",
    "pre": {
      "name": "pre",
      "from_marker": "function_entry",
      "to_marker": "before_first_external_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_first_external_call",
      "to_marker": "after_last_external_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_last_external_call",
      "to_marker": "function_exit"
    },
    "linearization_point": "after_last_external_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tracks the balance mid-transfer during `yeetyeet` execution.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum_deposits == balance + inFlight",
    "stable_formula": "_sum_deposits == balance",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum_deposits == balance",
    "rule": "The exposure invariant `conserve` ensures that the sum of deposits and in-flight balance conserves over reentrant calls, which maintains the target property."
  }
}
